WITH parsed AS (SELECT id, tier_limits, tier_prices, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT CASE WHEN lowest_price >= 28 THEN 'HIGH' ELSE 'LOW' END AS lowest_price_tier, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS num_rows, COUNT(*) AS event_count, ROUND(AVG(lowest_price), 2) AS avg_lowest_price, APPROX_PERCENTILE(lowest_price, 0.9) AS lowest_price_p90, MAX(avg_tier_price) AS max_avg_tier_price FROM parsed GROUP BY CASE WHEN lowest_price >= 28 THEN 'HIGH' ELSE 'LOW' END HAVING COUNT(*) >= 1 ORDER BY lowest_price_p90 NULLS LAST;
